public final class MarinkaGameTests {
    @GameTest(template="empty",timeoutTicks=600) public static void builtYardAndHatch(GameTestHelper t){
        var w=t.getLevel();var p=player(t);var center=new BlockPos(512,0,203172);var actors=new ArrayList<Entity>();
        for(int cx=(center.getX()-31)>>4;cx<=((center.getX()+31)>>4);cx++)for(int cz=(center.getZ()-31)>>4;cz<=((center.getZ()+31)>>4);cz++)w.setChunkForced(cx,cz,true);
        for(int x=-31;x<=31;x++)for(int z=-31;z<=31;z++){var at=center.offset(x,0,z);w.getChunkAt(at);for(int y=-11;y<=14;y++)w.setBlock(at.offset(0,y,0),(y<=0?Blocks.STONE:Blocks.AIR).defaultBlockState(),2);}
        for(int x=-6;x<=6;x++)for(int z=31;z<=40;z++)w.setBlock(center.offset(x,0,z),Blocks.STONE.defaultBlockState(),2);
        p.moveTo(center.getX()+.5,1,center.getZ()+.5);w.setBlock(center,Blocks.WATER.defaultBlockState(),2);t.assertTrue(!WitchYard.place(p,center,0),"Fluid site accepted");w.setBlock(center,Blocks.DIAMOND_BLOCK.defaultBlockState(),2);t.assertTrue(!WitchYard.place(p,center,0),"Player building overwritten");w.setBlock(center,Blocks.STONE.defaultBlockState(),2);w.setBlock(center.offset(-20,-1,20),Blocks.AIR.defaultBlockState(),2);t.assertTrue(WitchYard.place(p,center,0),"Safe staging rejected");
        var d=WitchYard.get(w);var e=d.near(center.getCenter());
        t.startSequence().thenWaitUntil(()->t.assertTrue(e.status==WitchYard.Status.READY,"Yard still building: "+e.status+" "+e.cursor)).thenExecute(()->{
            t.assertTrue(w.getBlockState(e.at(0,1,0)).is(MarinkaContent.SEAL.get()),"Seal missing");
            t.assertTrue(w.getBlockState(e.at(-20,-1,20)).is(Blocks.STONE),"Uneven foundation unsupported");
            t.assertTrue(w.getBlockState(e.at(0,0,1)).is(Blocks.CHISELED_DEEPSLATE),"Hatch not sealed");
            t.assertTrue(w.getBlockState(e.at(-7,-9,-8)).isAir(),"Workshop clearance");
            var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)w.getBlockEntity(e.at(3,-9,-9));t.assertTrue(chest!=null&&chest.getItem(10).is(Items.EMERALD),"Ordinary loot missing");chest.setItem(10,ItemStack.EMPTY);chest.setChanged();
            var h=MarinkaContent.DOBRYNYA.get().create(w);h.owner=p.getUUID();h.moveTo(e.at(-2,1,0).getBottomCenter());w.addFreshEntity(h);d.heroes.put(p.getUUID(),h.getUUID());actors.add(h);
            var ilya=BogatyrContent.ILYA.get().create(w);ilya.owner=p.getUUID();ilya.moveTo(e.at(-5,1,3).getBottomCenter());ilya.setHealth(100);w.addFreshEntity(ilya);BogatyrLedger.get(w).heroes.put(p.getUUID(),ilya.getUUID());actors.add(ilya);
            t.assertTrue(WitchYard.start(p,e.at(0,1,0),false),"Story entrance rejected matching hero");t.assertTrue(ilya.getHealth()==100&&e.standby.equals(ilya.getUUID())&&ilya.getZ()>=center.getZ()+30,"Ilya was replaced/healed/not parked outside yard");
            var other=player(t);other.moveTo(p.position());t.assertTrue(!WitchYard.start(other,e.at(0,1,0),false),"Second player entered occupied yard");clean(other);actors.add(w.getEntity(e.boss));
        }).thenIdle(80).thenExecute(()->{var b=(MarinkaEntity)w.getEntity(e.boss);b.hurt(p.damageSources().playerAttack(p),1000);t.assertTrue(e.status==WitchYard.Status.WON&&d.progress.get(p.getUUID()).getInt("DefeatCount")==1,"Actual lethal player hit did not record victory once");t.assertTrue(d.progress.get(p.getUUID()).getBoolean("dobrynya_released")&&!d.progress.get(p.getUUID()).getBoolean("dobrynya_anchor_broken"),"Victory release confused with anchor rescue");})
        .thenIdle(30).thenExecute(()->t.assertTrue(e.status==WitchYard.Status.WON,"Opened too early"))
        .thenIdle(30).thenExecute(()->{t.assertTrue(e.status==WitchYard.Status.OPEN,"Hatch deadline");for(int x=0;x<2;x++)for(int z=0;z<3;z++)t.assertTrue(w.getBlockState(e.at(x,0,z)).isAir(),"Hatch clearance");var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)w.getBlockEntity(e.at(3,-9,-9));t.assertTrue(chest.getItem(10).isEmpty(),"Victory refilled loot");p.moveTo(e.at(2,-9,-9).getBottomCenter());var click=new net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickBlock(p,net.minecraft.world.InteractionHand.MAIN_HAND,e.at(3,-9,-9),new net.minecraft.world.phys.BlockHitResult(e.at(3,-9,-9).getCenter(),net.minecraft.core.Direction.WEST,e.at(3,-9,-9),false));net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(click);t.assertTrue(d.progress.get(p.getUUID()).getBoolean("marinka_basement_discovered"),"Missing persisted discovery flag");t.assertTrue(((IlyaEntity)actors.get(1)).getHealth()==100&&!StoryPolicy.standby(p.getUUID(),w),"Ilya not restored without healing");d.yards.remove(e.id);for(int cx=(center.getX()-31)>>4;cx<=((center.getX()+31)>>4);cx++)for(int cz=(center.getZ()-31)>>4;cz<=((center.getZ()+31)>>4);cz++)w.setChunkForced(cx,cz,false);BogatyrLedger.get(w).heroes.remove(p.getUUID());clean(p,actors.toArray(Entity[]::new));}).thenSucceed();
    }
    @GameTest(template="empty",timeoutTicks=35) public static void rageCastClock(GameTestHelper t){var p=player(t);var b=boss(t,p);b.phase=3;b.begin(WitchAction.FIRE);t.assertTrue(b.length()==19,"Rage cast not faster");t.runAtTickTime(9,()->t.assertTrue(t.getLevel().getEntitiesOfClass(WitchBolt.class,b.getBoundingBox().inflate(5)).isEmpty(),"Early cast"));t.runAtTickTime(12,()->{t.assertTrue(t.getLevel().getEntitiesOfClass(WitchBolt.class,b.getBoundingBox().inflate(8)).size()==3,"Skipped/duplicated scaled release");b.cleanup();clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=35) public static void crossDimensionCanonical(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);var nether=p.server.getLevel(net.minecraft.world.level.Level.NETHER);t.assertTrue(StoryPolicy.standby(p.getUUID(),nether),"Dimension bypasses personal lock");t.assertTrue(WitchYard.get(nether).heroes.isEmpty(),"Per-dimension hero copy");clean(p,h,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void sweepOnce(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.face(b);h.begin(WitchAction.SWEEP);t.runAtTickTime(18,()->{t.assertTrue(b.getHealth()==585,"Sweep duplicate/missing hit "+b.getHealth());t.assertTrue(p.getHealth()==24,"Sweep hit friendly owner");clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=35) public static void reflectOne(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.face(b);h.begin(WitchAction.WARD);var shots=new ArrayList<WitchBolt>();for(int i=0;i<2;i++){var s=MarinkaContent.BOLT.get().create(t.getLevel());s.boss=b.getUUID();s.arena=b.arena;s.setOwner(b);s.moveTo(h.position().add(i*.2,1,-1));s.launch(new Vec3(0,0,.05));t.getLevel().addFreshEntity(s);shots.add(s);}t.runAtTickTime(8,()->{t.assertTrue(shots.stream().filter(s->s.reflected).count()==1&&b.exposed(),"Ward did not reflect exactly one");shots.forEach(Entity::discard);clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=40) public static void spellbreakerWindow(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);b.deflected(h);h.face(b);h.begin(WitchAction.UNRAVEL);t.runAtTickTime(15,()->{t.assertTrue(!b.veil()&&!b.exposed()&&!b.ready("restore_seal")&&!b.ready("veil"),"Spellbreaker failed");clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=35) public static void dyingHeroKeepsStoryLock(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.setHealth(1);h.hurt(h.damageSources().generic(),100);t.assertTrue(!h.isAlive()&&!StoryPolicy.canSummon(p,"dobrynya_nikitich")&&!StoryPolicy.canSummon(p,"ilya_muromets"),"Dead retreat freed story slot");clean(p,h,b);t.succeed();}
    private static final class Connection extends net.minecraft.network.Connection {
        private final io.netty.channel.embedded.EmbeddedChannel channel=new io.netty.channel.embedded.EmbeddedChannel();
        Connection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}@Override public io.netty.channel.Channel channel(){return channel;}
    }
    private static final class Listener extends net.minecraft.server.network.ServerGamePacketListenerImpl {
        Listener(ServerPlayer p){super(p.getServer(),new Connection(),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false));}
        @Override public void send(net.minecraft.network.protocol.Packet<?> p){}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener l){}
    }
    @SuppressWarnings("unchecked") private static Map<UUID,ServerPlayer> online(ServerPlayer p){try{var f=net.minecraft.server.players.PlayerList.class.getDeclaredField("playersByUUID");f.setAccessible(true);return (Map<UUID,ServerPlayer>)f.get(p.server.getPlayerList());}catch(Exception e){throw new RuntimeException(e);}}
    private static ServerPlayer player(GameTestHelper t){var w=t.getLevel();var p=new ServerPlayer(w.getServer(),w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"BogatyrTest"),ClientInformation.createDefault());p.connection=new Listener(p);p.setGameMode(GameType.SURVIVAL);try{var f=ServerPlayer.class.getDeclaredField("spawnInvulnerableTime");f.setAccessible(true);f.setInt(p,0);}catch(Exception e){throw new RuntimeException(e);}p.setNoGravity(true);p.moveTo(t.absoluteVec(new Vec3(16,2,18)));p.setOnGround(true);p.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(24);p.setHealth(24);w.addNewPlayer(p);online(p).put(p.getUUID(),p);return p;}
    private static void diamond(ServerPlayer p){p.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.DIAMOND_HELMET));p.setItemSlot(EquipmentSlot.CHEST,new ItemStack(Items.DIAMOND_CHESTPLATE));p.setItemSlot(EquipmentSlot.LEGS,new ItemStack(Items.DIAMOND_LEGGINGS));p.setItemSlot(EquipmentSlot.FEET,new ItemStack(Items.DIAMOND_BOOTS));p.doTick();if(p.getArmorValue()!=20)throw new AssertionError("Fixture armor not applied: "+p.getArmorValue());}
    private static void floor(GameTestHelper t){for(int x=0;x<48;x++)for(int z=0;z<48;z++)t.setBlock(new BlockPos(x,1,z),Blocks.STONE);}
    private static WitchYard.Entry yard(GameTestHelper t){floor(t);var e=new WitchYard.Entry(UUID.randomUUID(),t.absolutePos(new BlockPos(16,1,16)),0);e.status=WitchYard.Status.COMBAT;WitchYard.get(t.getLevel()).yards.put(e.id,e);return e;}
    private static MarinkaEntity boss(GameTestHelper t,ServerPlayer p){var e=yard(t);e.owner=p.getUUID();var b=MarinkaContent.MARINKA.get().create(t.getLevel());b.arena=e.id;b.owner=p.getUUID();b.active=true;b.debug=true;e.boss=b.getUUID();t.getLevel().addFreshEntity(b);b.moveTo(t.absoluteVec(new Vec3(16,2,12)));b.setTarget(p);b.face(p);b.begin(WitchAction.EXHAUSTED,10000);return b;}
    private static DobrynyaEntity hero(GameTestHelper t,ServerPlayer p,MarinkaEntity b){var h=MarinkaContent.DOBRYNYA.get().create(t.getLevel());h.owner=p.getUUID();h.moveTo(t.absoluteVec(new Vec3(16,2,15)));if(b!=null){h.bind(b.yard());b.yard().hero=h.getUUID();}t.getLevel().addFreshEntity(h);var d=WitchYard.get(t.getLevel());d.heroes.put(p.getUUID(),h.getUUID());h.begin(WitchAction.EXHAUSTED,10000);return h;}
    private static void clean(ServerPlayer p,Entity... mobs){online(p).remove(p.getUUID());var d=WitchYard.get(p.serverLevel());d.heroes.remove(p.getUUID());d.progress.remove(p.getUUID());for(var e:new ArrayList<>(d.yards.values()))if(p.getUUID().equals(e.owner)){e.status=WitchYard.Status.READY;d.yards.remove(e.id);}p.discard();for(var e:mobs)e.discard();}
    private static void damage(GameTestHelper t,String kind,float raw,float net){var p=player(t);diamond(p);var b=boss(t,p);p.hurt(MarinkaEntity.source(b,kind),raw);float actual=24-p.getHealth();System.out.println("MARINKA_DIAMOND kind="+kind+" raw="+raw+" armor="+p.getArmorValue()+" net="+actual);t.assertTrue(Math.abs(actual-net)<.02,"Actual damage "+kind+" "+actual);clean(p,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=35) public static void coreStats(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);t.assertTrue(b.getMaxHealth()==600&&h.getMaxHealth()==230,"HP");t.assertTrue(Math.abs(h.getBbWidth()-.8)<.001&&Math.abs(h.getBbHeight()-2.2)<.001,"Hero collision");t.assertTrue(Math.abs(b.getBbHeight()-1.96)<.001,"Boss collision");clean(p,h,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=35) public static void fireDiamond(GameTestHelper t){damage(t,"fire",17.5F,6.5625F);}
    @GameTest(template="empty",timeoutTicks=35) public static void sideDiamond(GameTestHelper t){damage(t,"fire",10,3);}
    @GameTest(template="empty",timeoutTicks=35) public static void traceDiamond(GameTestHelper t){damage(t,"trace",11.2F,3.4944F);}
    @GameTest(template="empty",timeoutTicks=35) public static void lureDiamond(GameTestHelper t){damage(t,"lure",7.32F,2.0006F);}
    @GameTest(template="empty",timeoutTicks=35) public static void rageDiamond(GameTestHelper t){damage(t,"rage",17.5F,6.5625F);}
    @GameTest(template="empty",timeoutTicks=35) public static void resistance(GameTestHelper t){var p=player(t);diamond(p);var b=boss(t,p);p.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.DAMAGE_RESISTANCE,100));p.hurt(MarinkaEntity.source(b,"fire"),17.5F);t.assertTrue(Math.abs(24-p.getHealth()-5.25)<.02,"Resistance bypass");clean(p,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=35) public static void physicalPassive(GameTestHelper t){var p=player(t);var h=hero(t,p,null);h.hurt(p.damageSources().generic(),20);t.assertTrue(h.getHealth()==215,"Hero passive");h.invulnerableTime=0;h.hurt(p.damageSources().magic(),20);t.assertTrue(h.getHealth()==195,"Magic must not use physical passive");clean(p,h);t.succeed();}
    @GameTest(template="empty",timeoutTicks=50) public static void comboFrames(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.setTarget(b);h.face(b);h.begin(WitchAction.COMBO);t.runAtTickTime(4,()->t.assertTrue(b.getHealth()==600,"Early combo"));t.runAtTickTime(8,()->t.assertTrue(b.getHealth()==591,"Hit1"));t.runAtTickTime(15,()->t.assertTrue(b.getHealth()==581,"Hit2 hp="+b.getHealth()+" edge="+h.edge(b)+" hero="+h.position()+" boss="+b.position()));t.runAtTickTime(25,()->{t.assertTrue(b.getHealth()==566,"Hit3/multiple events "+b.getHealth());clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=40) public static void thrustFrame(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.setTarget(b);h.face(b);h.begin(WitchAction.THRUST);t.runAtTickTime(6,()->t.assertTrue(b.getHealth()==600,"Early thrust"));t.runAtTickTime(10,()->{t.assertTrue(b.getHealth()==579,"Thrust21");clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=40) public static void thrustWall(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);for(int y=2;y<=5;y++)for(int x=14;x<=18;x++)t.setBlock(new BlockPos(x,y,14),Blocks.STONE);h.setTarget(b);h.face(b);h.begin(WitchAction.THRUST);t.runAtTickTime(12,()->{t.assertTrue(b.getHealth()==600,"Thrust through wall");clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=45) public static void parrySingle(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.face(b);h.begin(WitchAction.PARRY);t.runAtTickTime(5,()->{h.hurt(MarinkaEntity.source(b,"lure"),20);t.assertTrue(h.getHealth()==210,"Magic incorrectly parried");h.invulnerableTime=0;h.hurt(b.damageSources().mobAttack(b),20);t.assertTrue(Math.abs(h.getHealth()-205.5)<.02,"70percent one parry");h.invulnerableTime=0;h.hurt(b.damageSources().mobAttack(b),20);t.assertTrue(Math.abs(h.getHealth()-190.5)<.02,"Second parry reused");clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=40) public static void resolveFinite(GameTestHelper t){var p=player(t);var h=hero(t,p,null);h.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.WEAKNESS,100));t.assertTrue(h.getEffect(net.minecraft.world.effect.MobEffects.WEAKNESS).getDuration()==65,"Resolve duration");h.removeEffect(net.minecraft.world.effect.MobEffects.WEAKNESS);t.assertTrue(!h.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.WEAKNESS,100)),"Control reapplied before12seconds");clean(p,h);t.succeed();}
    @GameTest(template="empty",timeoutTicks=80) public static void transformUuid(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);UUID id=h.getUUID();h.setHealth(100);h.transform(700);t.runAtTickTime(31,()->{t.assertTrue(h.bull()&&h.getUUID().equals(id)&&h.getHealth()==100,"Transform lost actor");t.assertTrue(Math.abs(h.getBbWidth()-1.15)<.01,"Bull collision");h.revert();});t.runAtTickTime(49,()->{t.assertTrue(!h.bull()&&h.getUUID().equals(id)&&h.getHealth()==100,"Revert lost HP/UUID");clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=35) public static void partyLock(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);t.assertTrue(!StoryPolicy.canSummon(p,"ilya_muromets")&&!StoryPolicy.canSummon(p,"dobrynya_nikitich"),"Midfight replacement allowed");h.transform(700);t.assertTrue(!StoryPolicy.canSummon(p,"ilya_muromets"),"Curse freed slot");var guest=player(t);var bystander=player(t);b.contribution(guest);t.assertTrue(!StoryPolicy.canSummon(guest,"ilya_muromets")&&!StoryPolicy.canSummon(guest,"dobrynya_nikitich"),"Participant bypassed story lock");t.assertTrue(StoryPolicy.canSummon(bystander,"ilya_muromets"),"Unrelated player was bound to story");clean(guest);clean(bystander);WitchYard.fail(t.getLevel(),b.yard());t.assertTrue(StoryPolicy.canSummon(p,"ilya_muromets"),"Released lock stuck");clean(p,h,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=55) public static void veilThirtyPercent(GameTestHelper t){var p=player(t);var b=boss(t,p);b.begin(WitchAction.VEIL);t.runAtTickTime(6,()->t.assertTrue(!b.veil(),"Instant veil"));t.runAtTickTime(10,()->{t.assertTrue(b.veil(),"Veil absent");b.hurt(p.damageSources().playerAttack(p),20);t.assertTrue(Math.abs(b.getHealth()-586)<.01,"Barrier not30percent");b.breakWard();t.assertTrue(!b.veil(),"Broken remains active");clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=230) public static void veilUptimeBounded(GameTestHelper t){var p=player(t);var b=boss(t,p);b.begin(WitchAction.VEIL);t.runAtTickTime(20,()->b.begin(WitchAction.EXHAUSTED,10000));t.runAtTickTime(193,()->{t.assertTrue(!b.veil(),"Veil beyond9seconds");clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=45) public static void clonesExactlyThree(GameTestHelper t){var p=player(t);var b=boss(t,p);b.begin(WitchAction.SHADOW);t.runAtTickTime(16,()->{var copies=t.getLevel().getEntitiesOfClass(MarinkaEntity.class,new net.minecraft.world.phys.AABB(b.yard().center).inflate(32),m->b.encounter.equals(m.encounter));t.assertTrue(copies.size()==3,"Bodies "+copies.size());t.assertTrue(copies.stream().filter(MarinkaEntity::falseBody).count()==2,"Real count");t.assertTrue(copies.stream().allMatch(m->m.getType()==b.getType()&&m.action()==WitchAction.IDLE),"Visible identity leak");for(var c:copies)if(c!=b)c.discard();clean(p,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=55) public static void falseTwentyFour(GameTestHelper t){var p=player(t);var b=boss(t,p);var c=MarinkaContent.MARINKA.get().create(t.getLevel());c.parent=b.getUUID();c.arena=b.arena;c.owner=p.getUUID();c.active=true;c.moveTo(b.position());t.getLevel().addFreshEntity(c);c.begin(WitchAction.EXHAUSTED,10000);c.hurt(p.damageSources().playerAttack(p),12);t.assertTrue(c.action()!=WitchAction.CLONE_BREAK,"Clone broke before24");c.invulnerableTime=0;c.hurt(p.damageSources().playerAttack(p),12);t.assertTrue(c.action()==WitchAction.CLONE_BREAK,"Clone not broken24");t.assertTrue(b.getHealth()==600,"Clone reduced real HP");clean(p,c,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=35) public static void burstGroup(GameTestHelper t){var p=player(t);var b=boss(t,p);var c=MarinkaContent.MARINKA.get().create(t.getLevel());c.parent=b.getUUID();c.arena=b.arena;c.owner=p.getUUID();c.active=true;t.getLevel().addFreshEntity(c);t.assertTrue(b.burst()&&!c.burst()&&!b.burst(),"Grouped heavy burst cap");clean(p,c,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=35) public static void cloneDamageScale(GameTestHelper t){var p=player(t);diamond(p);var b=boss(t,p);var c=MarinkaContent.MARINKA.get().create(t.getLevel());c.parent=b.getUUID();c.arena=b.arena;c.owner=p.getUUID();c.active=true;t.getLevel().addFreshEntity(c);p.hurt(MarinkaEntity.source(c,"fire"),17.5F);t.assertTrue(Math.abs(24-p.getHealth()-2.953125)<.02,"Clone effective45percent");clean(p,c,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=35) public static void anchorThreeStrikes(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.transform(700);var a=MarinkaContent.ANCHOR.get().create(t.getLevel());a.boss=b.getUUID();a.arena=b.arena;t.getLevel().addFreshEntity(a);for(int i=0;i<3;i++){a.invulnerableTime=0;a.hurt(p.damageSources().playerAttack(p),1);}t.assertTrue(a.isRemoved()&&b.rescued&&h.action()==WitchAction.REVERT&&!b.veil(),"Anchor reversal");clean(p,h,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=35) public static void anchorRejectsMob(GameTestHelper t){var p=player(t);var b=boss(t,p);var a=MarinkaContent.ANCHOR.get().create(t.getLevel());a.boss=b.getUUID();a.arena=b.arena;t.getLevel().addFreshEntity(a);t.assertTrue(!a.hurt(b.damageSources().mobAttack(b),100)&&a.getHealth()==80,"Boss broke its anchor");clean(p,a,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=260) public static void retreatFinite(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);h.setHealth(34.5F);h.begin(WitchAction.IDLE);t.runAtTickTime(3,()->t.assertTrue(h.retreated&&h.recovering(),"15percent no retreat"));t.runAtTickTime(95,()->t.assertTrue(h.getHealth()<=106&&!h.bull(),"Drink above cap"));t.runAtTickTime(220,()->{t.assertTrue(!h.recovering()&&h.getHealth()<=106&&h.getHealth()>34.5,"No finite recovery");h.setHealth(34);h.tick();t.assertTrue(h.action()!=WitchAction.RETREAT,"Second retreat resets budget");clean(p,h,b);t.succeed();});}
    @GameTest(template="empty",timeoutTicks=40) public static void victoryOnce(GameTestHelper t){var p=player(t);var b=boss(t,p);b.debug=false;b.contribution(p);var e=b.yard();var d=WitchYard.get(t.getLevel());d.victory(t.getLevel(),e,b);d.victory(t.getLevel(),e,b);t.assertTrue(d.progress.get(p.getUUID()).getInt("DefeatCount")==1&&e.status==WitchYard.Status.WON,"Double victory");clean(p,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void falseNoVictory(GameTestHelper t){var p=player(t);var b=boss(t,p);var c=MarinkaContent.MARINKA.get().create(t.getLevel());c.parent=b.getUUID();c.arena=b.arena;c.owner=p.getUUID();c.active=true;t.getLevel().addFreshEntity(c);c.die(p.damageSources().playerAttack(p));t.assertTrue(b.yard().status==WitchYard.Status.COMBAT&&!WitchYard.get(t.getLevel()).progress.containsKey(p.getUUID()),"False victory unlocked cellar");clean(p,c,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void failureSealed(GameTestHelper t){var p=player(t);var b=boss(t,p);var e=b.yard();WitchYard.fail(t.getLevel(),e);t.assertTrue(e.status==WitchYard.Status.READY&&!WitchYard.get(t.getLevel()).progress.containsKey(p.getUUID()),"Failure awarded");clean(p,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void savedDataRoundtrip(GameTestHelper t){var p=player(t);var b=boss(t,p);var h=hero(t,p,b);var d=WitchYard.get(t.getLevel());var tag=d.save(new CompoundTag(),t.getLevel().registryAccess());var loaded=WitchYard.load(tag,t.getLevel().registryAccess());t.assertTrue(loaded.heroes.get(p.getUUID()).equals(h.getUUID())&&loaded.lock(p.getUUID()).hero.equals(h.getUUID()),"Canonical/lock lost");clean(p,h,b);t.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void thirtyNineSounds(GameTestHelper t){t.assertTrue(MarinkaContent.CUES.size()==39,"Cue count");for(var name:MarinkaContent.CUES)t.assertTrue(net.minecraft.core.registries.BuiltInRegistries.SOUND_EVENT.getKey(MarinkaContent.sound(name)).equals(MarinkaContent.id(name)),"Registry missing "+name);t.succeed();}
}
